prose = label() # initially blank text

def keyInput(evt):
    s = evt.key
    if len(s) == 1: # includes enter ('\n')
        prose.text += s # append new character
    elif ( s == 'delete' or s is 'backspace' ) and len(prose.text) > 0:
        prose.text = prose.text[:-1] # erase letter

